tool_calls.arguments:
{"command":"kubectl patch statefulset app -n default --type=strategic -p '{
  "spec": {
    "volumeClaimTemplates": [
      {
        "apiVersion": "v1",
        "kind": "PersistentVolumeClaim",
        "metadata": {"labels":{"app":"app"},"name":"data"},
        "spec": {
          "accessModes": ["ReadWriteOnce"],
          "resources": {"requests":{"storage":"1Gi"}},
          "storageClassName": "standard"
        }
      }
    ]
  }
}'; echo "patched"; kubectl get sts app -n default -o jsonpath='{.metadata.generation}{"\n"}'; sleep 5; kubectl get pvc -n default; echo "--- pods ---"; kubectl get pods -n default"}

